def conditional_put(connect,name,expected,new_generation,data):
    if not isinstance(name,str) or not name or any(type(x) is not int or not 0<=x<2**63 for x in (expected,new_generation)) or new_generation==0 or new_generation==expected or type(data) is not bytes:raise ValueError('finite generation model')
    connection=connect()
    try:
        if expected==0:
            try:cursor=connection.execute('INSERT INTO objects VALUES(?,?,?)',(name,new_generation,data))
            except sqlite3.IntegrityError:return False
        else:cursor=connection.execute('UPDATE objects SET generation=?,payload=? WHERE name=? AND generation=?',(new_generation,data,name,expected))
        return cursor.rowcount==1
    finally:connection.close()
