import copy,datetime
def add_timed_reader(policy,member,expires):
    if not isinstance(member,str) or not member.startswith('serviceAccount:') or not isinstance(expires,str):raise ValueError('service identity and aware expiry')
    end=datetime.datetime.fromisoformat(expires.replace('Z','+00:00'))
    if end.tzinfo is None:raise ValueError('aware expiry')
    if end.microsecond:raise ValueError('whole-second expiry required')
    if any(member in binding['members'] for binding in policy['bindings']):raise ValueError('new member required; preserve original effective permissions')
    end=end.astimezone(datetime.timezone.utc).isoformat(timespec='seconds').replace('+00:00','Z')
    result=copy.deepcopy(policy);result['version']=3
    result['bindings'].append({'role':'roles/storage.objectViewer','members':[member],'condition':{'title':'training-expiry','expression':'request.time < timestamp("'+end+'")'}})
    return result
